WITH exploded AS (SELECT id, customer_id, created_at, item.product_id, item.qty, item.price, item.promo FROM carts LATERAL VIEW OUTER EXPLODE(items) e AS item) SELECT promo, product_id, SORT_ARRAY(COLLECT_SET(promo)) AS promo_list, COUNT(DISTINCT customer_id) AS distinct_customer_ids, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min, MAX(qty) FILTER (WHERE promo = 'VIP') AS vip_max_qty, GROUPING_ID() AS gid FROM exploded GROUP BY ROLLUP (promo, product_id);
